/// Programs to run: one that shows its arguments, and some that fail in different ways.
final class XargsFixtures {
  let root: String

  init() {
    var template = Array("/tmp/xargstestXXXXXX".utf8CString)
    root = template.withUnsafeMutableBufferPointer { String(cString: mkdtemp($0.baseAddress!)) }
    script("show", "l=; for a; do l=\"$l[$a]\"; done; echo \"$l\"")
    script("fail1", "echo \"args: $*\"; exit 1")
    script("fail255", "echo \"args: $*\"; exit 255")
    script("sig", "echo \"args: $*\"; kill -9 $$")
    script("fail2nd", "echo \"args: $*\"; [ \"$1\" = bad ] && exit 3; exit 0")
  }

  func script(_ name: String, _ body: String) {
    let text = "#!/bin/sh\n" + body + "\n"
    let fd = open(root + "/" + name, O_CREAT | O_WRONLY | O_TRUNC, 0o755)
    _ = text.withCString { write(fd, $0, strlen($0)) }
    close(fd)
    chmod(root + "/" + name, 0o755)
  }

  /// What the results were recorded with: the programs in front of the usual directories.
  func environment() -> [String: String] {
    ["PATH": "\(root):/usr/bin:/bin", "LC_ALL": "C"]
  }

  func remove() {
    for name in ["show", "fail1", "fail255", "sig", "fail2nd"] {
      unlink(root + "/" + name)
    }
    rmdir(root)
  }
}

