    let fixtures = XargsFixtures()
    defer { fixtures.remove() }
    try await run(withStdin: "a b\n", output: "a\nb\n", error: "", args: "-n1", "sh", "-c", "echo $1", "x", env: fixtures.environment(), cd: FilePath(fixtures.root))
    try await run(withStdin: "a b\n", output: "a b\n", error: "", args: "echo", env: fixtures.environment(), cd: FilePath(fixtures.root))
    try await run(withStdin: "a b\n", output: "a b", error: "", args: "echo", "-n", env: fixtures.environment(), cd: FilePath(fixtures.root))
  }

  /// With more than one process at a time the order of the output is not fixed, but all of it is there.
  @Test(arguments: ["-P2", "-P3", "-P0", "--max-procs=2"])
  func severalAtATime(_ option: String) async throws {
    let fixtures = XargsFixtures()
    defer { fixtures.remove() }
    try await run(withStdin: "a b c d e f g h\n", args: [option, "-n1", "show"], env: fixtures.environment(), cd: FilePath(fixtures.root)) { po in
      #expect(po.code == 0)
      let lines = String(decoding: po.data, as: UTF8.self).split(separator: "\n").sorted()
      #expect(lines == ["[a]", "[b]", "[c]", "[d]", "[e]", "[f]", "[g]", "[h]"])
    }
  }

  /// A command that fails with 255 (or by a signal) stops it: the ones already running are waited for.
  @Test func failureStopsTheReading() async throws {
    let fixtures = XargsFixtures()
    defer { fixtures.remove() }
    try await run(withStdin: "a\nb\nc\n", status: 1, output: "args: a\n", error: "xargs: fail255: exited with status 255; aborting\n", args: "-n1", "fail255", env: fixtures.environment(), cd: FilePath(fixtures.root))
  }

  @Test func theProgramFindsItsInputAtTheNull() async throws {
    // standard input of the commands is /dev/null, not the input of xargs
    try await run(withStdin: "a\n", output: "\n", error: "", args: "sh", "-c", "cat; echo", env: ["PATH": "/usr/bin:/bin"])
  }
}
